public class MyCircularQueue {
    private readonly int[] a;
    private int head, count;      // хвост не хранится: (head + count) % a.Length

    public MyCircularQueue(int k) => a = new int[k];

    public bool EnQueue(int value) {
        if (count == a.Length) return false;        // полно: отказ, ничего не затираем
        a[(head + count) % a.Length] = value;       // следующая свободная, за концом — снова 0
        count++;
        return true;
    }

    public bool DeQueue() {
        if (count == 0) return false;
        head = (head + 1) % a.Length;               // старое значение остаётся в массиве, но вне очереди
        count--;
        return true;
    }

    public int Front() => count == 0 ? -1 : a[head];

    public int Rear() => count == 0 ? -1 : a[(head + count - 1) % a.Length];

    public bool IsEmpty() => count == 0;

    public bool IsFull() => count == a.Length;
}

