public sealed class History<T> {          // последние cap значений, старые затираются
    readonly T[] buf;
    readonly uint mask;
    uint tail;                              // всего записано; не заворачивается

    public History(int capPow2) { buf = new T[capPow2]; mask = (uint)capPow2 - 1; }

    public int Count => (int)Math.Min(tail, (uint)buf.Length);

    public void Push(T value) => buf[tail++ & mask] = value;

    public T Ago(int i) => buf[(tail - 1 - (uint)i) & mask];   // 0 — последнее, i < Count
}

